import{_ as a,c as e,o as i,b0 as l}from"./chunks/framework.CLL9SSSf.js";const n="data:image/png;base64,",t="/linux-driver-docs/assets/018_repeated_start.euME-jWm.png",r="/linux-driver-docs/assets/019_smbus_quick_command.B02JvwVY.png",o="/linux-driver-docs/assets/020_smbus_receive_byte.SqaaWzKR.png",c="/linux-driver-docs/assets/021_smbus_send_byte.CjMdozO3.png",p="/linux-driver-docs/assets/022_smbus_read_byte.DQYgqeNn.png",d="/linux-driver-docs/assets/023_smbus_read_word.wN7fxAU3.png",u="/linux-driver-docs/assets/024_smbus_write_byte.46lOwzcy.png",b="/linux-driver-docs/assets/025_smbus_write_word.BMImEWU1.png",h="/linux-driver-docs/assets/026_smbus_block_read.D6BPwcmy.png",m="/linux-driver-docs/assets/027_smbus_block_write.Dh7JdIIm.png",k="/linux-driver-docs/assets/033_i2c_block_read.BoDiu8gi.png",g="/linux-driver-docs/assets/034_i2c_block_write.CIyxeIA0.png",C="/linux-driver-docs/assets/028_smbus_block_write_block_read_process_call.CkYE90tD.png",_="/linux-driver-docs/assets/029_smbus_pec_example.CObCXsxt.png",w=JSON.parse('{"title":"LV050-SMBus协议简介","description":null,"frontmatter":{"title":"LV050-SMBus协议简介","date":"2026-01-21T17:13:01.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/kdriver/drv-i2c/126d2d5355651bf2bcca8db0","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-21T17:13:01.447Z","fulluuid":"2bcca8db00bb446d9bf2cd166b9ea21c","useduuid":"2bcca8db0"}},"headers":[],"relativePath":"sdoc/kdriver/drv-i2c/126d2d5355651bf2bcca8db0.md","filePath":"sdoc/07-设备驱动子系统/07-i2c/LV050-SMBus协议简介.md","lastUpdated":1769002717000}'),B={name:"sdoc/kdriver/drv-i2c/126d2d5355651bf2bcca8db0.md"};function y(F,s,S,v,M,f){return i(),e("div",null,[...s[0]||(s[0]=[l('<h1 id="lv050-smbus协议简介" tabindex="-1">LV050-SMBus协议简介 <a class="header-anchor" href="#lv050-smbus协议简介" aria-label="Permalink to &quot;LV050-SMBus协议简介&quot;">​</a></h1><p>了解下 SMBus 协议。若笔记中有错误或者不合适的地方，欢迎批评指正 😃。</p><h2 id="一、smbus-是-i2c-协议的一个子集" tabindex="-1">一、SMBus 是 I2C 协议的一个子集 <a class="header-anchor" href="#一、smbus-是-i2c-协议的一个子集" aria-label="Permalink to &quot;一、SMBus 是 I2C 协议的一个子集&quot;">​</a></h2><h3 id="_1-smbus-是什么" tabindex="-1">1. SMBus 是什么？ <a class="header-anchor" href="#_1-smbus-是什么" aria-label="Permalink to &quot;1. SMBus 是什么？&quot;">​</a></h3><p>SMBus: System Management Bus，系统管理总线。SMBus 最初的目的是为智能电池、充电电池、其他微控制器之间的通信链路而定义的。也被用来连接各种设备，包括电源相关设备，系统传感器，EEPROM 通讯设备等等。</p><p>SMBus 为系统和电源管理这样的任务提供了一条控制总线，使用 SMBus 的系统，设备之间发送和接收消息都是通过 SMBus，而不是使用单独的控制线，这样可以节省设备的管脚数。</p><p>SMBus 是基于 I2C 协议的，SMBus 要求更严格，SMBus 是 I2C 协议的子集。</p><img src="'+n+'" alt="image-20210224093827621" style="zoom:50%;"><h3 id="_2-有哪些更严格的要求" tabindex="-1">2. 有哪些更严格的要求？ <a class="header-anchor" href="#_2-有哪些更严格的要求" aria-label="Permalink to &quot;2. 有哪些更严格的要求？&quot;">​</a></h3><p>SMBus 有哪些更严格的要求？跟一般的 I2C 协议有哪些差别？</p><ul><li>VDD 的极限值不一样</li></ul><p>I2C 协议：范围很广，甚至讨论了高达 12V 的情况。</p><p>SMBus：1.8V~5V。</p><ul><li>最小时钟频率、最大的 <code>Clock Stretching</code></li></ul><p>Clock Stretching 就是某个设备需要更多时间进行内部的处理时，它可以把 SCL 拉低占住 I2C 总线。</p><p>I2C 协议：时钟频率最小值无限制，Clock Stretching 时长也没有限制。</p><p>SMBus：时钟频率最小值是 10KHz，Clock Stretching 的最大时间值也有限制</p><ul><li>地址回应(Address Acknowledge)（一个 I2C 设备接收到它的设备地址后，是否必须发出回应信号？）</li></ul><p>I2C 协议：没有强制要求必须发出回应信号</p><p>SMBus：强制要求必须发出回应信号，这样对方才知道该设备的状态：busy，failed，或是被移除了</p><ul><li>SMBus 协议明确了数据的传输格式</li></ul><p>I2C 协议：它只定义了怎么传输数据，但是并没有定义数据的格式，这完全由设备来定义</p><p>SMBus：定义了几种数据格式(后面分析)</p><ul><li>REPEATED START Condition(重复发出 S 信号)</li></ul><p>比如读 EEPROM 时，涉及 2 个操作：把存储地址发给设备和读数据。在写、读之间，可以不发出 P 信号，而是直接发出 S 信号：这个 S 信号就是 <code>REPEATED START</code>，如下图所示</p><img src="'+t+`" alt="image-20210224100056055" style="zoom:80%;"><ul><li>SMBus Low Power Version ：SMBus 也有低功耗的版本。</li></ul><h2 id="二、smbus-协议分析" tabindex="-1">二、SMBus 协议分析 <a class="header-anchor" href="#二、smbus-协议分析" aria-label="Permalink to &quot;二、SMBus 协议分析&quot;">​</a></h2><p>对于 I2C 协议，它只定义了怎么传输数据，但是并没有定义数据的格式，这完全由设备来定义。对于 SMBus 协议，它定义了几种数据格式。需要注意：</p><ul><li>下面文档中的 <code>Functionality flag</code> 是 Linux 的某个 I2C 控制器驱动所支持的功能。</li><li>比如 <code>Functionality flag: I2C_FUNC_SMBUS_QUICK</code>，表示需要 I2C 控制器支持 <code>SMBus Quick Command</code></li></ul><h3 id="_1-symbols-符号" tabindex="-1">1. symbols(符号) <a class="header-anchor" href="#_1-symbols-符号" aria-label="Permalink to &quot;1. symbols(符号)&quot;">​</a></h3><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S     (1 bit) : Start bit(开始位)</span></span>
<span class="line"><span>Sr    (1 bit) : 重复的开始位</span></span>
<span class="line"><span>P     (1 bit) : Stop bit(停止位)</span></span>
<span class="line"><span>R/W#  (1 bit) : Read/Write bit. Rd equals 1, Wr equals 0.(读写位)</span></span>
<span class="line"><span>A, N  (1 bit) : Accept and reverse accept bit.(回应位)</span></span>
<span class="line"><span>Address(7 bits): I2C 7 bit address. Note that this can be expanded as usual to</span></span>
<span class="line"><span>                get a 10 bit I2C address.</span></span>
<span class="line"><span>                (地址位，7位地址)</span></span>
<span class="line"><span>Command Code  (8 bits): Command byte, a data byte which often selects a register on</span></span>
<span class="line"><span>                the device.</span></span>
<span class="line"><span>                (命令字节，一般用来选择芯片内部的寄存器)</span></span>
<span class="line"><span>Data Byte (8 bits): A plain data byte. Sometimes, I write DataLow, DataHigh</span></span>
<span class="line"><span>                for 16 bit data.</span></span>
<span class="line"><span>                (数据字节，8位；如果是16位数据的话，用2个字节来表示：DataLow、DataHigh)</span></span>
<span class="line"><span>Count (8 bits): A data byte containing the length of a block operation.</span></span>
<span class="line"><span>				(在block操作总，表示数据长度)</span></span>
<span class="line"><span>[..]:           Data sent by I2C device, as opposed to data sent by the host</span></span>
<span class="line"><span>                adapter.</span></span>
<span class="line"><span>                (中括号表示I2C设备发送的数据，没有中括号表示host adapter发送的数据)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h3 id="_2-smbus-quick-command" tabindex="-1">2. SMBus Quick Command <a class="header-anchor" href="#_2-smbus-quick-command" aria-label="Permalink to &quot;2. SMBus Quick Command&quot;">​</a></h3><img src="`+r+'" alt="image-20210224105224903" style="zoom:67%;"><p>只是用来发送一位数据：R/W#本意是用来表示读或写，但是在 SMBus 里可以用来表示其他含义。比如某些开关设备，可以根据这一位来决定是打开还是关闭。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_QUICK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-接收-发送一个字节——不发-command-code" tabindex="-1">3. 接收/发送一个字节——不发 Command Code <a class="header-anchor" href="#_3-接收-发送一个字节——不发-command-code" aria-label="Permalink to &quot;3. 接收/发送一个字节——不发 Command Code&quot;">​</a></h3><h4 id="_3-1-smbus-receive-byte" tabindex="-1">3.1 SMBus Receive Byte <a class="header-anchor" href="#_3-1-smbus-receive-byte" aria-label="Permalink to &quot;3.1 SMBus Receive Byte&quot;">​</a></h4><img src="'+o+'" alt="image-20210224113511225" style="zoom:67%;"><p>读取一个字节，可以看 I2C-tools 中的函数 <a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L53" target="_blank" rel="noreferrer">i2c_smbus_read_byte()</a>。Host adapter 接收到一个字节后不需要发出回应信号(上图中 N 表示不回应)。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_READ_BYTE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_3-2-smbus-send-byte" tabindex="-1">3.2 SMBus Send Byte <a class="header-anchor" href="#_3-2-smbus-send-byte" aria-label="Permalink to &quot;3.2 SMBus Send Byte&quot;">​</a></h4><img src="'+c+'" alt="image-20210224110638143" style="zoom:67%;"><p>发送一个字节，可以看 I2C-tools 中的函数 <a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L65" target="_blank" rel="noreferrer">i2c_smbus_write_byte()</a>。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_WRITE_BYTE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_4-接收-发送一个字节——发送-command-code" tabindex="-1">4. 接收/发送一个字节——发送 Command Code <a class="header-anchor" href="#_4-接收-发送一个字节——发送-command-code" aria-label="Permalink to &quot;4. 接收/发送一个字节——发送 Command Code&quot;">​</a></h3><h4 id="_4-1-smbus-read-byte" tabindex="-1">4.1 SMBus Read Byte <a class="header-anchor" href="#_4-1-smbus-read-byte" aria-label="Permalink to &quot;4.1 SMBus Read Byte&quot;">​</a></h4><img src="'+p+'" alt="image-20210224110812872" style="zoom:67%;"><p>可以看 I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L71" target="_blank" rel="noreferrer">i2c_smbus_read_byte_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再读取一个字节的数据。上面介绍的 <code>SMBus Receive Byte</code> 是不发送 Comand，直接读取数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_READ_BYTE_DATA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-2-smbus-read-word" tabindex="-1">4.2 SMBus Read Word <a class="header-anchor" href="#_4-2-smbus-read-word" aria-label="Permalink to &quot;4.2 SMBus Read Word&quot;">​</a></h4><img src="'+d+'" alt="image-20210224111404096" style="zoom:67%;"><p>可以看 I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L92" target="_blank" rel="noreferrer">i2c_smbus_read_word_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再读取 2 个字节的数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_READ_WORD_DATA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-3-smbus-write-byte" tabindex="-1">4.3 SMBus Write Byte <a class="header-anchor" href="#_4-3-smbus-write-byte" aria-label="Permalink to &quot;4.3 SMBus Write Byte&quot;">​</a></h4><img src="'+u+'" alt="image-20210224111542576" style="zoom:67%;"><p>I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L84" target="_blank" rel="noreferrer">i2c_smbus_write_byte_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再发出 1 个字节的数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_WRITE_BYTE_DATA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-4-smbus-write-word" tabindex="-1">4.4 SMBus Write Word <a class="header-anchor" href="#_4-4-smbus-write-word" aria-label="Permalink to &quot;4.4 SMBus Write Word&quot;">​</a></h4><img src="'+b+'" alt="image-20210224111840257" style="zoom:67%;"><p>I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L105" target="_blank" rel="noreferrer">i2c_smbus_write_word_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再发出 1 个字节的数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_WRITE_WORD_DATA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-5-smbus-block-read" tabindex="-1">4.5 SMBus Block Read <a class="header-anchor" href="#_4-5-smbus-block-read" aria-label="Permalink to &quot;4.5 SMBus Block Read&quot;">​</a></h4><img src="'+h+'" alt="image-20210224112524185" style="zoom:67%;"><p>I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L125" target="_blank" rel="noreferrer">i2c_smbus_read_block_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再发起读操作：先读到一个字节(Block Count)，表示后续要读的字节数，然后读取全部数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_READ_BLOCK_DATA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-6-smbus-block-write" tabindex="-1">4.6 SMBus Block Write <a class="header-anchor" href="#_4-6-smbus-block-write" aria-label="Permalink to &quot;4.6 SMBus Block Write&quot;">​</a></h4><img src="'+m+'" alt="image-20210224112629201" style="zoom:67%;"><p>I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L140" target="_blank" rel="noreferrer">i2c_smbus_write_block_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再发出 1 个字节的 <code>Byte Conut</code>(表示后续要发出的数据字节数)，最后发出全部数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_WRITE_BLOCK_DATA</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-7-i2c-block-read" tabindex="-1">4.7 I2C Block Read <a class="header-anchor" href="#_4-7-i2c-block-read" aria-label="Permalink to &quot;4.7 I2C Block Read&quot;">​</a></h4><p>在一般的 I2C 协议中，也可以连续读出多个字节。它跟 <code>SMBus Block Read</code> 的差别在于设备发出的第 1 个数据不是长度 N，如下图所示：</p><img src="'+k+'" alt="image-20210225094024082" style="zoom:80%;"><p>I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L158" target="_blank" rel="noreferrer">i2c_smbus_read_i2c_block_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再发出 1 个字节的 <code>Byte Conut</code>(表示后续要发出的数据字节数)，最后发出全部数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_READ_I2C_BLOCK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_4-8-i2c-block-write" tabindex="-1">4.8 I2C Block Write <a class="header-anchor" href="#_4-8-i2c-block-write" aria-label="Permalink to &quot;4.8 I2C Block Write&quot;">​</a></h4><p>在一般的 I2C 协议中，也可以连续发出多个字节。它跟 <code>SMBus Block Write</code> 的差别在于发出的第 1 个数据不是长度 N，如下图所示：</p><img src="'+g+'" alt="image-20210225094359443" style="zoom:80%;"><p>I2C-tools 中的函数：<a href="https://github.com/oudream/i2c-tools/blob/master/lib/smbus.c#L179" target="_blank" rel="noreferrer">i2c_smbus_write_i2c_block_data()</a>。先发出 <code>Command Code</code>(它一般表示芯片内部的寄存器地址)，再发出 1 个字节的 <code>Byte Conut</code>(表示后续要发出的数据字节数)，最后发出全部数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_WRITE_I2C_BLOCK</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_5-smbus-block-write-block-read-process-call" tabindex="-1">5. SMBus Block Write - Block Read Process Call <a class="header-anchor" href="#_5-smbus-block-write-block-read-process-call" aria-label="Permalink to &quot;5. SMBus Block Write - Block Read Process Call&quot;">​</a></h3><img src="'+C+'" alt="image-20210224112940865" style="zoom:67%;"><p>先写一块数据，再读一块数据。</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Functionality</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flag:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I2C_FUNC_SMBUS_BLOCK_PROC_CALL</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_6-packet-error-checking-pec" tabindex="-1">6. Packet Error Checking (PEC) <a class="header-anchor" href="#_6-packet-error-checking-pec" aria-label="Permalink to &quot;6. Packet Error Checking (PEC)&quot;">​</a></h3><p>PEC 是一种错误校验码，如果使用 PEC，那么在 P 信号之前，数据发送方要发送一个字节的 PEC 码(它是 CRC-8 码)。</p><p>以 <code>SMBus Send Byte</code> 为例，下图中，一个未使用 PEC，另一个使用 PEC：</p><img src="'+_+'" alt="image-20210224113416249" style="zoom:67%;"><h2 id="三、smbus-和-i2c-的建议" tabindex="-1">三、SMBus 和 I2C 的建议 <a class="header-anchor" href="#三、smbus-和-i2c-的建议" aria-label="Permalink to &quot;三、SMBus 和 I2C 的建议&quot;">​</a></h2><p>因为很多设备都实现了 SMBus，而不是更宽泛的 I2C 协议，所以优先使用 SMBus。即使 I2C 控制器没有实现 SMBus，软件方面也是可以使用 I2C 协议来模拟 SMBus。所以：Linux 建议优先使用 SMBus。</p><blockquote><p>参考资料：</p><ul><li><p>Linux 内核文档：<a href="https://elixir.bootlin.com/linux/v4.19.71/source/Documentation/i2c/smbus-protocol" target="_blank" rel="noreferrer">smbus-protocol - Documentation/i2c/smbus-protocol</a></p></li><li><p>SMBus 协议：<a href="http://www.smbus.org/specs/" target="_blank" rel="noreferrer">http://www.smbus.org/specs/</a></p></li><li><p>文档：System Management Bus (SMBus) Specification</p></li><li><p>I2CTools: <a href="https://archive.kernel.org/oldwiki/i2c.wiki.kernel.org/index.php/I2C_Tools.html" target="_blank" rel="noreferrer">I2C Tools - Linux i2c Wiki</a></p></li></ul></blockquote>',91)])])}const x=a(B,[["render",y]]);export{w as __pageData,x as default};
